import sys


def main():
    seen = set()
    for line in sys.stdin:
        key = line.rstrip('\t').strip().lower()
        if key:
            if key not in seen:
                seen.add(key)
                print(line.rstrip('\t').rstrip())


if __name__ == "__main__":
    main()
